solution.solution.cpp:
struct Vec2
{
    double x{};
    double y{};
};

Vec2 operator+(const Vec2& a, const Vec2& b)
{
    return { a.x + b.x, a.y + b.y };
}

Vec2 operator-(const Vec2& a, const Vec2& b)
{
    return { a.x - b.x, a.y - b.y };
}

Vec2 operator*(const Vec2& v, double k)
{
    return { v.x * k, v.y * k };
}

Vec2 operator*(double k, const Vec2& v)
{
    return v * k;
}

bool operator==(const Vec2& a, const Vec2& b)
{
    return a.x == b.x && a.y == b.y;
}

Vec2 operator-(const Vec2& v)
{
    return { -v.x, -v.y };
}

unitTests:
TEST("add and subtract") { const Vec2 a{ 1, 2 }, b{ 3, 5 }; CHECK((a + b) == (Vec2{ 4, 7 })); CHECK((b - a) == (Vec2{ 2, 3 })); }
TEST("scale from either side") { const Vec2 v{ 1.5, -2 }; CHECK((v * 2.0) == (Vec2{ 3, -4 })); CHECK((2.0 * v) == (Vec2{ 3, -4 })); }
TEST("negate") { CHECK((-Vec2{ 1, -2 }) == (Vec2{ -1, 2 })); }
TEST("equality") { CHECK(Vec2{ 1, 2 } == Vec2{ 1, 2 }); CHECK(!(Vec2{ 1, 2 } == Vec2{ 1, 3 })); }
TEST("in a bigger expression") { const Vec2 p{ 1, 2 }, v{ 3, 4 }; CHECK((p + v * 2.0) == (Vec2{ 7, 10 })); }

